import { setContext, getContext } from "svelte";
import { getParentPaths, getVisiblePaths } from "./utils.js";
import type { Props } from "./index.js";
import type { FileTreeNode } from "./utils.js";

const CONTEXT_ID = "file-tree-context";

class UseCompCtx {
	/** Files and folders built from the `files` prop */
	tree: FileTreeNode[] = $state([]);
	/** Path of the selected file; empty while none is selected */
	value = $state("");
	/** Paths of the open folders */
	expanded: string[] = $state([]);
	/** Paths drawn with the highlight, such as search matches */
	highlighted: ReadonlySet<string> = $state(new Set());
	/** Blocks file selection; folders still open and close */
	disabled = $state(false);
	/** Path of the last focused item */
	focused = $state("");
	/** Custom icon for every item */
	icon?: Props["icon"] = $state();
	/** Content after every item's name */
	trailing?: Props["trailing"] = $state();
	/** Called with the path when a file is selected */
	onValueChange?: Props["onValueChange"];
	/** Called with the open folder paths when a folder opens or closes */
	onExpandedChange?: Props["onExpandedChange"];
	/** Paths of the items on screen in order */
	visiblePaths = $derived(getVisiblePaths(this.tree, this.expanded));
	/** Path of the one item Tab reaches: the last focused item, else the selected file, else the first item */
	tabStop = $derived([this.focused, this.value].find((path) => this.visiblePaths.includes(path)) ?? this.visiblePaths[0] ?? "");

	// Set default data
	constructor(props: { [key: string]: any }) {
		// Merge props into this instance (we do not use `Object.assign(this, props)` to ensure only setting props that exists)
		for (const [key, data] of Object.entries(props)) {
			// @ts-ignore
			if (this[key] !== undefined) this[key] = data;
		}
	}

	/** Whether a folder is open. */
	isExpanded(path: string) {
		return this.expanded.includes(path);
	}

	/** Selects a file and reports the change. */
	select(path: string) {
		// If selection is disabled or the file is already selected: skip the update.
		if (this.disabled || path === this.value) return;
		this.value = path;
		this.onValueChange?.(path);
	}

	/** Opens or closes a folder and reports the change. */
	setExpanded(path: string, open: boolean) {
		// If the folder is already in that state: skip the update.
		if (open === this.isExpanded(path)) return;
		this.expanded = open ? [...this.expanded, path] : this.expanded.filter((expandedPath) => expandedPath !== path);
		this.onExpandedChange?.(this.expanded);
	}

	/** Opens a closed folder or closes an open one. */
	toggle(path: string) {
		this.setExpanded(path, !this.isExpanded(path));
	}

	/** Opens every folder around a path, so a file selected from outside the tree is on screen. */
	reveal(path: string) {
		for (const parentPath of getParentPaths(path)) this.setExpanded(parentPath, true);
	}
}

export type CompCtxProps = Pick<InstanceType<typeof UseCompCtx>, "tree" | "value" | "expanded" | "highlighted" | "disabled" | "icon" | "trailing" | "onValueChange" | "onExpandedChange">;

export const setCompCtx = (props: CompCtxProps) => setContext(CONTEXT_ID, new UseCompCtx(props));

export const useCompCtx = () => getContext<ReturnType<typeof setCompCtx>>(CONTEXT_ID);

export { default as FileTree } from "./_.svelte";
export { default as FileTreeIcon } from "./icon.svelte";
export type { FileTreeNode } from "./utils.js";

/** Values a custom `icon` or `trailing` snippet receives for each item */
export interface ItemSnippetProps {
	/** Full path of the file or folder */
	path: string;
	/** Whether the item is a folder */
	isFolder: boolean;
	/** Whether the folder is open; always `false` for files */
	open: boolean;
	/** Whether the file is selected; always `false` for folders */
	selected: boolean;
}

/** Tree of files and folders built from paths, with one selectable file */
export interface Props extends CompProps<"ul"> {
	/** File paths, or an object keyed by path, such as editor files; a path ending in `/` is an empty folder */
	files: string[] | Record<string, unknown>;
	/** Path of the selected file; supports `bind:value` */
	value?: string;
	/** Called with the path when a file is selected */
	onValueChange?: (value: string) => void;
	/** Paths of the open folders; every folder starts open when omitted; supports `bind:expanded` */
	expanded?: string[];
	/** Called with the open folder paths when a folder opens or closes */
	onExpandedChange?: (expanded: string[]) => void;
	/** File paths drawn with the highlight, such as search matches */
	highlighted?: string[];
	/** Blocks file selection; folders still open and close */
	disabled?: boolean;
	/** Custom icon for every item; replaces the language and folder icons */
	icon?: Snippet<[ItemSnippetProps]>;
	/** Content after every item's name, such as a badge or an action */
	trailing?: Snippet<[ItemSnippetProps]>;
	/** `default` draws no box; `outline` draws a bordered card around the tree */
	variant?: "default" | "outline";
	/** Row height, text, icons, and indent on the shared scale; defaults to `md` */
	size?: UiSize;
	/** Corner radius of the box; rows use one step smaller; follows `size` when omitted */
	rounded?: UiRounded;
	/** Classes merged onto the tree */
	class?: CompProps<"ul">["class"];
}

/** Icon picked from a path's extension, or an open or closed folder */
export interface IconProps {
	/** File or folder path; the extension picks the file icon */
	path: string;
	/** Draws a folder instead of a file icon */
	isFolder?: boolean;
	/** Draws the open folder; only used with `isFolder` */
	open?: boolean;
	/** Classes merged onto the icon */
	class?: string;
}

export type FileTreeProps = Props;
export type FileTreeIconProps = IconProps;
export type FileTreeItemSnippetProps = ItemSnippetProps;

/** A file or folder in the tree */
export interface FileTreeNode {
	/** Last segment of the path, shown as the label */
	name: string;
	/** Full path without leading or trailing slashes */
	path: string;
	/** Files and folders inside; set only on folders */
	children?: FileTreeNode[];
}

/** Builds a sorted tree from paths; a path that ends in `/`, or that other paths sit under, is a folder. */
export function buildFileTree(paths: Iterable<string>) {
	const root: FileTreeNode[] = [];
	for (const rawPath of paths) {
		// Drop empty segments, so leading, trailing, and double slashes add no nameless folders.
		const names = rawPath.split("/").filter(Boolean);
		const isFolderPath = rawPath.endsWith("/");
		let siblings = root;
		let path = "";
		for (const [index, name] of names.entries()) {
			path = path ? `${path}/${name}` : name;
			const isLast = index === names.length - 1;
			let node = siblings.find((sibling) => sibling.name === name);
			// If the segment is new: add it.
			if (!node) {
				node = { name, path };
				siblings.push(node);
			}
			// If the segment is the file itself: stop; anything else is a folder, even one first listed as a file.
			if (isLast && !isFolderPath) continue;
			node.children ??= [];
			siblings = node.children;
		}
	}
	return sortNodes(root);
}

/** Sorts folders before files, then by name with numbers in natural order, like VS Code. */
function sortNodes(nodes: FileTreeNode[]): FileTreeNode[] {
	nodes.sort((a, b) => {
		// If one is a folder and the other a file: the folder goes first.
		if (!a.children !== !b.children) return a.children ? -1 : 1;
		return a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" });
	});
	for (const node of nodes) if (node.children) sortNodes(node.children);
	return nodes;
}

/** Lists the path of every folder in the tree. */
export function getFolderPaths(nodes: FileTreeNode[]): string[] {
	return nodes.flatMap((node) => (node.children ? [node.path, ...getFolderPaths(node.children)] : []));
}

/** Lists the paths of the items on screen in order, skipping the contents of closed folders. */
export function getVisiblePaths(nodes: FileTreeNode[], expanded: string[]): string[] {
	return nodes.flatMap((node) => (node.children && expanded.includes(node.path) ? [node.path, ...getVisiblePaths(node.children, expanded)] : [node.path]));
}

/** Lists the folder paths that contain a path, from the top down. */
export function getParentPaths(path: string) {
	const names = path.split("/").slice(0, -1);
	return names.map((_, index) => names.slice(0, index + 1).join("/"));
}
